class ResizingHashMap:
    MAX_LOAD = 0.75

    def __init__(self, capacity=8):
        self._buckets = [[] for _ in range(capacity)]
        self._size = 0

    def _bucket(self, key):
        return self._buckets[hash(key) % len(self._buckets)]

    def put(self, key, value):
        bucket = self._bucket(key)
        for pair in bucket:
            if pair[0] == key:
                pair[1] = value
                return
        bucket.append([key, value])
        self._size += 1
        if self._size / len(self._buckets) > self.MAX_LOAD:
            self._resize(2 * len(self._buckets))

    def _resize(self, new_capacity):
        old = [pair for bucket in self._buckets for pair in bucket]
        self._buckets = [[] for _ in range(new_capacity)]
        for pair in old:
            self._bucket(pair[0]).append(pair)

    def get(self, key, default=None):
        for k, v in self._bucket(key):
            if k == key:
                return v
        return default

    def remove(self, key):
        bucket = self._bucket(key)
        for i, (k, _) in enumerate(bucket):
            if k == key:
                del bucket[i]
                self._size -= 1
                return
        raise KeyError(key)

    def __len__(self):
        return self._size

    def bucket_lengths(self):
        return [len(b) for b in self._buckets]

m = ResizingHashMap()
for i in range(100):
    m.put(i, i)
print(len(m.bucket_lengths()), max(m.bucket_lengths()))
```
8 → 16 at the 7th key, → 32 at the 13th, → 64 at the 25th, → 128 at the 49th, → 256 at the 97th.

