from collections import Counter

def top_k_frequent(items, k):
    return [item for item, _ in Counter(items).most_common(k)]

def top_k_bucket(items, k):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    buckets = [[] for _ in range(len(items) + 1)]
    for x, c in counts.items():
        buckets[c].append(x)
    out = []
    for c in range(len(buckets) - 1, 0, -1):
        for x in buckets[c]:
            out.append(x)
            if len(out) == k:
                return out
    return out

print(top_k_frequent(list("aabbbcdd"), 2), top_k_bucket(list("aabbbcdd"), 2))
```
No count can exceed n, so n + 1 buckets cover every possibility and nothing is sorted.

