from collections import defaultdict

def first_duplicate_event(events):
    seen = set()
    for e in events:
        if e in seen:
            return e
        seen.add(e)
    return None

def topics_per_student(events):
    d = defaultdict(set)
    for student, topic in events:
        d[student].add(topic)
    return {s: len(t) for s, t in d.items()}

ev = [("a", 1), ("b", 1), ("a", 2), ("a", 1)]
print(first_duplicate_event(ev), topics_per_student(ev))
