import re
from collections import Counter
import numpy as np

def words(text):
    return re.findall(r"[a-z]+", text.lower())

def vectorize(texts):
    vocab = sorted({w for t in texts for w in words(t)})
    rows = []
    for t in texts:
        c = Counter(words(t))
        rows.append([c[w] for w in vocab])
    return np.array(rows, dtype=float)

def most_similar(query, docs):
    X = vectorize(docs + [query])
    X = X / np.where(np.linalg.norm(X, axis=1, keepdims=True) == 0, 1, np.linalg.norm(X, axis=1, keepdims=True))
    scores = X[:-1] @ X[-1]
    return int(np.argmax(scores))

print(most_similar("why does my motor driver overheat", ["the motor stalls", "sensor reads noise", "motor driver gets hot"]))
```
"noisy sensor" matches doc 1 only through "sensor": "noisy" and "noise" are different words to a bag of words. That's the main weakness of counts, and the reason learned embeddings exist.

