class Stack:
    def __init__(self):
        self._items = []

    def push(self, x):
        self._items.append(x)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        return self._items[-1]

    def is_empty(self):
        return not self._items

    def __len__(self):
        return len(self._items)


class MinStack(Stack):
    def __init__(self):
        super().__init__()
        self._mins = []

    def push(self, x):
        super().push(x)
        self._mins.append(x if not self._mins else min(x, self._mins[-1]))

    def pop(self):
        x = super().pop()
        self._mins.pop()
        return x

    def min(self):
        return self._mins[-1]

