class QueueFromStacks:
    def __init__(self):
        self._in, self._out = [], []

    def enqueue(self, x):
        self._in.append(x)

    def dequeue(self):
        if not self._out:
            while self._in:
                self._out.append(self._in.pop())
        if not self._out:
            raise IndexError("dequeue from empty queue")
        return self._out.pop()

    def __len__(self):
        return len(self._in) + len(self._out)

q = QueueFromStacks()
for x in (1, 2, 3):
    q.enqueue(x)
print(q.dequeue(), len(q))
```
An element enters the inbox once, is poured into the outbox once and popped once, so n operations cost O(n) total even though a single dequeue can cost O(n).

